import { encodedLiteral, projectionFile } from "../rendering.js";
function screamingSnakeCase(value) {
    return value.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/[^A-Za-z0-9]+/g, "_").toUpperCase();
}
function render(definition, packageName) {
    const source = definition.sourcePointer.replace(/#$/, "");
    if (definition.kind === "enum") {
        const constants = definition.values.map((value) => `    ${screamingSnakeCase(String(value))}(${encodedLiteral("java", value)})`).join(",\n");
        return `package ${packageName};\n\n/** Projected from kernel/schemas/${source}. */\n` +
            "// GENERATED by tools/src/projection/providers/java/structural-projection-provider.ts — do not hand-edit.\n" +
            `public enum ${definition.typeName} {\n${constants};\n\n` +
            "    private final String wireValue;\n\n" +
            `    ${definition.typeName}(String wireValue) {\n        this.wireValue = wireValue;\n    }\n\n` +
            "    public String wireValue() {\n        return wireValue;\n    }\n}\n";
    }
    const needsList = definition.fields.some((field) => field.type.startsWith("List<"));
    const components = definition.fields.map((field) => `    ${field.type} ${field.name}`).join(",\n");
    const constants = definition.constants.map((constant) => `    public static final String ${constant.name} = ${encodedLiteral("java", constant.value)};`).join("\n");
    const body = constants ? ` {\n${constants}\n}` : " {}";
    return `package ${packageName};\n${needsList ? "\nimport java.util.List;\n" : ""}\n` +
        `/** Projected from kernel/schemas/${source}. */\n` +
        "// GENERATED by tools/src/projection/providers/java/structural-projection-provider.ts — do not hand-edit.\n" +
        `public record ${definition.typeName}(\n${components}\n)${body}\n`;
}
export class JavaStructuralProjectionProvider {
    target = "java";
    render(graph, profile) {
        if (graph.target !== this.target || profile.language !== this.target)
            throw new Error("Java renderer received another target.");
        if (!profile.namespace)
            throw new Error("Java projection profile does not declare a package namespace.");
        return {
            planType: "projection-plan.v1",
            target: this.target,
            outputDirectory: profile.outputDirectory,
            files: graph.definitions.map((definition) => projectionFile(`${definition.typeName}.java`, render(definition, profile.namespace), definition))
        };
    }
}
